    ('K6-V131', 59, 6545, '59176480355abbe75d798dce0d2e9164', 'auswahl', 'sachsituation', 'f5dcbd10291a3510a5cf2aa0c37db9e5', $rbf${"index": 2}$rbf$::jsonb, 'id.algebra.term', $rbf$[{"nr": 1, "art": "index", "luecke": null, "wert": "0", "text": "Klammer vergessen: die Äpfel werden zum Rückgeld addiert statt abgezogen", "fehlbild": null, "regel": null}, {"nr": 2, "art": "index", "luecke": null, "wert": "1", "text": "die 2 Äpfel zum Brezelpreis 0,80 € gerechnet und zusätzlich 0,60 € für einen Apfel noch einmal abgezogen", "fehlbild": null, "regel": null}, {"nr": 3, "art": "index", "luecke": null, "wert": "3", "text": "den Schein mit b malgenommen", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('K6-V132', 59, 6546, 'e6af1846e796a16315cf7c527e2d3d1b', 'zahl', 'sachsituation', null, $rbf${"wert": 60, "einheit": "min"}$rbf$::jsonb, 'id.algebra.term', $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "50", "text": "die Grundgebühren und die Minutenpreise addiert statt Unterschiede gebildet", "fehlbild": null, "regel": null}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "6", "text": "nur den Unterschied der Grundgebühren angegeben", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('K6-V133', 59, 6547, '4fba74a1731aa59c2fdf7097687e0203', 'luecken', 'muster', null, $rbf${"werte": [4, 6, 86]}$rbf$::jsonb, 'id.algebra.term', $rbf$[{"nr": 1, "art": "luecke", "luecke": 1, "wert": "14", "text": "das zweite Glied als Zuwachs genommen", "fehlbild": null, "regel": null}, {"nr": 2, "art": "luecke", "luecke": 2, "wert": "10", "text": "das erste Glied als Konstante genommen", "fehlbild": null, "regel": null}, {"nr": 3, "art": "luecke", "luecke": 3, "wert": "80", "text": "die Konstante vergessen", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('K6-V134', 59, 6548, '22e8e17bdca6a624cef518bc979eef9e', 'auswahl', 'muster', 'e7f8d9f18f1f2d217b2c79beef2483d1', $rbf${"index": 0}$rbf$::jsonb, 'id.algebra.term', $rbf$[{"nr": 1, "art": "index", "luecke": null, "wert": "1", "text": "den ersten Tabellenwert als Konstante genommen", "fehlbild": null, "regel": null}, {"nr": 2, "art": "index", "luecke": null, "wert": "2", "text": "nur die erste Zeile passend gewählt", "fehlbild": null, "regel": null}, {"nr": 3, "art": "index", "luecke": null, "wert": "3", "text": "mit dem ersten Wert malgenommen", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('K6-V135', 59, 6549, 'e3f35575ddf27397a2f68f9436e8fdb6', 'zahl', 'muster', null, $rbf${"wert": 6}$rbf$::jsonb, 'id.algebra.term', $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "6.75", "text": "die 3 vergessen: 27 : 4", "fehlbild": null, "regel": null}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "7.5", "text": "3 addiert statt abgezogen", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('K6-V136', 59, 6550, '561d15e7f3e2225627c18401c73288b3', 'luecken', 'deuten', null, $rbf${"werte": [47, 59, 41]}$rbf$::jsonb, 'id.algebra.term', $rbf$[{"nr": 1, "art": "luecke", "luecke": 1, "wert": "152", "text": "4x + 15 als (4 + 15) · x gerechnet: 19 · 8", "fehlbild": null, "regel": null}, {"nr": 2, "art": "luecke", "luecke": 2, "wert": "62", "text": "statt des Verlängerungspreises von 12 € erneut die Grundgebühr von 15 € addiert: 47 + 15", "fehlbild": null, "regel": null}, {"nr": 3, "art": "luecke", "luecke": 2, "wert": "50", "text": "nur 3 € statt 3 · 4 € dazugerechnet: 47 + 3", "fehlbild": null, "regel": null}, {"nr": 4, "art": "luecke", "luecke": 3, "wert": "53", "text": "nur den 8-Stunden-Preis vom Schein abgezogen: 100 − 47", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('K6-V137', 59, 6551, '346ccbdea9584f05ab258dce4c4f9797', 'auswahl', 'deuten', '18412f22efa86e4766242b1550ef99a3', $rbf${"index": 3}$rbf$::jsonb, 'id.algebra.term', $rbf$[{"nr": 1, "art": "index", "luecke": null, "wert": "0", "text": "x und Preis vertauscht", "fehlbild": null, "regel": null}, {"nr": 2, "art": "index", "luecke": null, "wert": "1", "text": "den Gesamtpreis mit dem Preis je Stunde verwechselt", "fehlbild": null, "regel": null}, {"nr": 3, "art": "index", "luecke": null, "wert": "2", "text": "Zahl der Stunden und Grundgebühr verwechselt", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('K6-V138', 59, 6552, '7babf34356dce21b73571db3da71c54d', 'auswahl', 'deuten', '6cb911a71d07c5765726ebd2cb6fd197', $rbf${"index": 0}$rbf$::jsonb, 'id.algebra.term', $rbf$[{"nr": 1, "art": "index", "luecke": null, "wert": "1", "text": "Für x = 2 ergibt 19x tatsächlich 38. Der Term 19x ist aber durch den Fehler in Zeile 1 entstanden; dort steht der erste Fehler.", "fehlbild": null, "regel": null}, {"nr": 2, "art": "index", "luecke": null, "wert": "2", "text": "Zeile 3 übernimmt nur den Wert aus Zeile 2. Der erste Fehler steht schon in Zeile 1.", "fehlbild": null, "regel": null}]$rbf$::jsonb)
  ) x(k, e, r, mt, y, l, ma, o, regel, fb) loop
    select count(*) into n from schule.aufgabe where einheit_id = z.e and pool = 'uebung' and reihenfolge = z.r;
    if n <> 1 then fehler := fehler || format('%s: %s Übungsaufgaben an Einheit %s, Platz %s', z.k, n, z.e, z.r); continue; end if;
    select * into a from schule.aufgabe where einheit_id = z.e and pool = 'uebung' and reihenfolge = z.r;
    if md5(coalesce(a.frage->>'text', '')) <> z.mt or a.antworttyp is distinct from z.y or a.variante_gruppe is distinct from z.l
       or (z.ma is not null and md5(coalesce((select string_agg(t.x, E'\n' order by t.o) from jsonb_array_elements_text(a.antworten) with ordinality t(x, o)), '')) <> z.ma) then
      fehler := fehler || format('%s: Aufgabe %s (Einheit %s, Platz %s) ist nicht die erwartete (Fragetext/Typ/Lernkarte/Antworten)', z.k, a.id, z.e, z.r); continue; end if;
    -- Lösung samt Einheit und Toleranz wie eingespielt (jsonb-Gleichheit: Zahlen werden als Zahlen verglichen, 12 = 12.0)
    if a.loesung is distinct from z.o then
      fehler := fehler || format('%s: Aufgabe %s (Einheit %s, Platz %s): Lösung %s statt %s wie eingespielt', z.k, a.id, z.e, z.r, a.loesung, z.o); continue; end if;
    if a.id = any(v_ids) then fehler := fehler || format('%s: Aufgabe %s doppelt zugeordnet', z.k, a.id); continue; end if;
    v_ids := v_ids || a.id;
    if z.regel is not null then
      insert into schule.aufgabe_regel (aufgabe_id, regel) values (a.id, z.regel) on conflict do nothing;
      get diagnostics c = row_count; n_regel_neu := n_regel_neu + c;
      if (select r.regel from schule.aufgabe_regel r where r.aufgabe_id = a.id) is distinct from z.regel then
        fehler := fehler || format('%s: Aufgabe %s hat schon eine andere Regel', z.k, a.id); end if;
    end if;
    for f in select * from jsonb_array_elements(z.fb) loop
      insert into schule.aufgabe_fehlbild (aufgabe_id, nr, art, luecke, wert, beschreibung, fehlbild, regel)
      values (a.id, (f->>'nr')::smallint, f->>'art', (f->>'luecke')::smallint, f->>'wert', f->>'text', f->>'fehlbild', f->>'regel') on conflict do nothing;
      get diagnostics c = row_count; n_fb_neu := n_fb_neu + c;
      select * into v_alt from schule.aufgabe_fehlbild x where x.aufgabe_id = a.id and x.nr = (f->>'nr')::smallint;
      if v_alt.nr is null or (v_alt.art, v_alt.luecke, v_alt.wert, v_alt.beschreibung, v_alt.fehlbild, v_alt.regel)
           is distinct from (f->>'art', (f->>'luecke')::smallint, f->>'wert', f->>'text', f->>'fehlbild', f->>'regel') then
        fehler := fehler || format('%s: Fehlbild %s steht schon anders da (oder gleicher Schlüssel unter anderer Nummer)', z.k, f->>'nr'); continue; end if;
      v := schule.fehlbild_probeantwort(a, f->>'art', (f->>'luecke')::int, f->>'wert');
      b := schule.antwort_bewerten(a, v);
      if not coalesce((b->>'format_ok')::boolean, false) or coalesce((b->>'richtig')::boolean, true) then
        fehler := fehler || format('%s: Fehlbild %s – Antwort %s wird nicht als gültig und falsch bewertet (%s)', z.k, f->>'nr', v, b); continue; end if;
      if schule.fehlbild_finden(a, v) is distinct from (f->>'nr')::smallint then
        fehler := fehler || format('%s: Fehlbild %s wird an der Antwort %s nicht wiedererkannt', z.k, f->>'nr', v); end if;
    end loop;
    if (select count(*) from schule.aufgabe_fehlbild x where x.aufgabe_id = a.id) <> jsonb_array_length(z.fb) then
      fehler := fehler || format('%s: Aufgabe %s hat andere Fehlbilder in der Datenbank als im Paket', z.k, a.id); end if;
  end loop;
  if array_length(fehler, 1) > 0 then raise exception 'RB-S Regelbezug ABBRUCH, alles zurückgerollt (% Befunde): %', array_length(fehler, 1), array_to_string(fehler[1:40], ' | '); end if;
  if coalesce(array_length(v_ids, 1), 0) <> 198
     or (select count(*) from schule.aufgabe_regel where aufgabe_id = any(v_ids)) <> 142
     or (select count(*) from schule.aufgabe_fehlbild where aufgabe_id = any(v_ids)) <> 534 then
    raise exception 'RB-S Regelbezug ABBRUCH: Zählung stimmt nicht (Aufgaben %, erwartet 198)', array_length(v_ids, 1); end if;
  raise notice 'RB-S Regelbezug: % Aufgaben, % Regeln neu, % Fehlbilder neu (zweiter Lauf: 0 und 0)', array_length(v_ids, 1), n_regel_neu, n_fb_neu;
end $rbnach$;
